def search(arr):
    left, right = 0, len(arr) - 1

    if len(arr) == 1:
        return arr[0]

    if arr[0] != arr[1]:
        return arr[0]

    if arr[-1] != arr[-2]:
        return arr[-1]

    while left <= right:
        mid = (left + right) // 2

        if arr[mid] != arr[mid - 1] and arr[mid] != arr[mid + 1]:
            return arr[mid]

        if mid % 2 == 0:
            if arr[mid] == arr[mid + 1]:
                left = mid + 2
            else:
                right = mid - 2
        else:
            if arr[mid] == arr[mid - 1]:
                left = mid + 1
            else:
                right = mid - 1

    return -1

def sum_of_divisors(n):
    if n <= 1:
        return 0
    divisors_sum = 1
    i = 2
    while i * i <= n:
        if n % i == 0:
            divisors_sum += i
            if i != n // i:
                divisors_sum += n // i
        i += 1
    return divisors_sum

