def find_solution(a, b, n):
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    def extended_gcd(x, y):
        if y == 0:
            return x, 1, 0
        g, x1, y1 = extended_gcd(y, x % y)
        return g, y1, x1 - (x // y) * y1

    g = gcd(a, b)

    if n % g != 0:
        return None

    _, x, y = extended_gcd(a, b)

    x *= n // g
    y *= n // g

    return (x, y)

