def newman_prime(n):
    def nsw(k):
        if k == 0:
            return 1
        if k == 1:
            return 1

        a, b = 1, 1
        for i in range(2, k + 1):
            a, b = b, 2 * b + a
        return b

    count = 0
    k = 0
    while count < n:
        s_k = nsw(k)
        if is_prime(s_k):
            count += 1
            if count == n:
                return s_k
        k += 1
    return -1

