def set_left_most_unset_bit(n):
    if n == 0:
        return 1

    # Find the position of the most significant bit
    temp = n
    msb_pos = 0
    while temp:
        temp >>= 1
        msb_pos += 1

    # Check each bit from left (MSB) to right
    for i in range(msb_pos - 1, -1, -1):
        if not (n & (1 << i)):
            return n | (1 << i)

    # If all bits are set, set the bit to the left of MSB
    return n | (1 << msb_pos)

