def get_total_number_of_sequences(m, n):
    if n == 0:
        return 1
    if n == 1:
        return m

    # dp[i][j] = number of sequences of length i ending with value j
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Base case: sequences of length 1
    for j in range(1, m + 1):
        dp[1][j] = 1

    # Fill the dp table
    for i in range(2, n + 1):
        for j in range(1, m + 1):
            # For a sequence ending with j, the previous element must be <= j // 2
            for prev in range(1, j // 2 + 1):
                dp[i][j] += dp[i - 1][prev]

    # Sum all sequences of length n
    result = sum(dp[n][j] for j in range(1, m + 1))
    return result

def get_total_number_of_sequences(n, m):
    memo = {}

    def count_sequences(length, max_value):
        if length == 1:
            return max_value

        if (length, max_value) in memo:
            return memo[(length, max_value)]

        total = 0
        for first_value in range(1, max_value + 1):
            next_max = first_value // 2
            if next_max >= 1:
                total += count_sequences(length - 1, next_max)

        memo[(length, max_value)] = total
        return total

    return count_sequences(n, m)

