def next_smallest_palindrome(n):
    s = str(n + 1)
    length = len(s)

    while True:
        if s == s[::-1]:
            return int(s)

        # Get the middle part and mirror it
        mid = length // 2

        # Check if all 9s
        if s == '9' * length:
            return int('1' + '0' * (length - 1) + '1')

        # For odd length
        if length % 2 == 1:
            left = s[:mid]
            middle = s[mid]
            right = s[mid + 1:]

            mirrored = left + middle + left[::-1]

            if int(mirrored) > n:
                return int(mirrored)
            else:
                # Increment middle part
                left_mid = s[:mid + 1]
                carry = 1
                left_mid_list = list(left_mid)
                for i in range(len(left_mid_list) - 1, -1, -1):
                    digit = int(left_mid_list[i]) + carry
                    if digit == 10:
                        left_mid_list[i] = '0'
                        carry = 1
                    else:
                        left_mid_list[i] = str(digit)
                        carry = 0
                        break

                if carry == 1:
                    s = str(int(s) + 1)
                    length = len(s)
                else:
                    left_mid = ''.join(left_mid_list)
                    s = left_mid + left_mid[-2::-1]
                    return int(s)
        else:
            left = s[:mid]
            right = s[mid:]

            mirrored = left + left[::-1]

            if int(mirrored) > n:
                return int(mirrored)
            else:
                # Increment left part
                carry = 1
                left_list = list(left)
                for i in range(len(left_list) - 1, -1, -1):
                    digit = int(left_list[i]) + carry
                    if digit == 10:
                        left_list[i] = '0'
                        carry = 1
                    else:
                        left_list[i] = str(digit)
                        carry = 0
                        break

                if carry == 1:
                    s = str(int(s) + 1)
                    length = len(s)
                else:
                    left = ''.join(left_list)
                    s = left + left[::-1]
                    return int(s)

