def comb(n, r):
    if r > n or r < 0:
        return 0
    if r == 0 or r == n:
        return 1

    numerator = 1
    denominator = 1

    for i in range(r):
        numerator *= (n - i)
        denominator *= (i + 1)

    return numerator // denominator

